#!/usr/bin/env node
// Generates TypeScript types from every *.schema.json in the repository into
// src/generated/schemas/. Schemas reference each other by their $id
// (https://opensimpv.org/schema/...); those references are resolved to the
// local files, never fetched. Run `npm run gen:types`; CI runs it with --check.
//
// Generated files are read-only. To change a type, change the schema (engine
// side, by the owner of that schema) and regenerate.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const webRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
// The repository root is the nearest folder above apps/web that holds the engine
// (geometry/). Normally that is ../.., but a staged copy of the frontend kept in its
// own folder inside the repository (for example RawiBumi_PhaseF_F3_*) resolves to
// the real root, so it generates the same types.
function findRepoRoot(start) {
  for (let dir = path.resolve(start, "../.."); ; dir = path.dirname(dir)) {
    if (fs.existsSync(path.join(dir, "geometry")) && fs.existsSync(path.join(dir, "apps"))) return dir;
    if (path.dirname(dir) === dir) return path.resolve(start, "../..");
  }
}
const repoRoot = findRepoRoot(webRoot);
const OUT = path.join(webRoot, "src/generated/schemas");
const check = process.argv.includes("--check");
const SKIP_DIRS = new Set(["node_modules", ".git", "dist", "ui-a", "generated"]);
const SKIP_TOP = /^RawiBumi_(Standalone|PhaseF)/;

function findSchemas(dir, depth = 0) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith(".") || SKIP_DIRS.has(entry.name)) continue;
    if (depth === 0 && SKIP_TOP.test(entry.name)) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...findSchemas(full, depth + 1));
    else if (entry.name.endsWith(".schema.json")) out.push(full);
  }
  return out;
}

const files = findSchemas(repoRoot).sort();
const byId = new Map();
const byBase = new Map();
for (const file of files) {
  const schema = JSON.parse(fs.readFileSync(file, "utf8"));
  if (schema.$id) byId.set(schema.$id.replace(/#$/, ""), file);
  const base = path.basename(file);
  if (byBase.has(base)) throw new Error(`Duplicate schema file name ${base}: ${byBase.get(base)} and ${file}`);
  byBase.set(base, file);
}

const localResolver = {
  order: 1,
  canRead: (ref) => /^https?:\/\/opensimpv\.org\/schema\//.test(ref.url),
  read: (ref) => {
    const url = ref.url.replace(/#.*$/, "");
    const file = byId.get(url) ?? byBase.get(url.split("/").pop());
    if (!file) throw new Error(`No local schema for ${url}`);
    return fs.readFileSync(file, "utf8");
  }
};

const BANNER = (rel) =>
  `/* Generated by scripts/gen-types.mjs from ${rel}. Do not edit; change the schema and run npm run gen:types. */`;

const expected = new Map();
for (const file of files) {
  const rel = path.relative(repoRoot, file).split(path.sep).join("/");
  const schema = JSON.parse(fs.readFileSync(file, "utf8"));
  const name = path.basename(file, ".schema.json");
  const ts = await compile(schema, name, {
    bannerComment: BANNER(rel),
    cwd: path.dirname(file),
    additionalProperties: false,
    unreachableDefinitions: false,
    strictIndexSignatures: true,
    style: { printWidth: 110, singleQuote: false },
    $refOptions: { resolve: { opensimpv: localResolver, http: false, https: false } }
  });
  expected.set(path.join(OUT, `${name}.ts`), ts);
}

if (!check) fs.mkdirSync(OUT, { recursive: true });
const existing = fs.existsSync(OUT) ? fs.readdirSync(OUT).map((f) => path.join(OUT, f)) : [];
let stale = 0;
for (const [file, content] of expected) {
  // Compare with LF line endings so a Windows checkout (core.autocrlf) does not read as stale.
  const current = fs.existsSync(file) ? fs.readFileSync(file, "utf8").replace(/\r\n/g, "\n") : null;
  if (current === content) continue;
  if (check) {
    console.error(`Out of date: ${path.relative(webRoot, file)}`);
    stale++;
  } else fs.writeFileSync(file, content);
}
for (const file of existing) {
  if (expected.has(file)) continue;
  console.error(`Not produced by any schema (remove it): ${path.relative(webRoot, file)}`);
  stale++;
}
if (stale) {
  if (check) console.error("Run npm run gen:types.");
  process.exit(1);
}
console.log(`${check ? "Checked" : "Generated"} ${expected.size} type files from ${files.length} schemas.`);
